32	  height: calc(var(--u) * 4.1); padding: 0 calc(var(--u) * 3.0); border-radius: calc(var(--u) * 2.1); white-space: nowrap;
33	  background: linear-gradient(180deg, #7a2bb0, #4f1489); border: calc(var(--u)*0.22) solid #ffd36b;
34	  box-shadow: inset 0 calc(var(--u)*0.3) calc(var(--u)*0.5) rgba(255,255,255,0.25), 0 0 calc(var(--u)*1.2) rgba(255,190,90,0.45);
35	  display: flex; align-items: center; }
36	#hud .banner span { font-weight: 800; font-style: italic; font-size: calc(var(--u) * 2.45); letter-spacing: calc(var(--u)*0.06);
37	  background: linear-gradient(180deg, #fffbe8 0%, #ffe9a8 55%, #ffd36b 100%); -webkit-background-clip: text; background-clip: text; color: transparent;
38	  filter: drop-shadow(0 calc(var(--u)*0.12) 0 rgba(80,0,90,0.6)); display: inline-block; transform: skewX(-8deg); }
39	#hud .hidden { display: none !important; }
40	#hud .victory { position: absolute; left: 50%; bottom: calc(var(--u) * 3.4); transform: translateX(-50%); width: calc(var(--u) * 49); height: calc(var(--u) * 13.5); }
41	#hud .victory .pill { position: absolute; left: calc(var(--u)*8.5); right: calc(var(--u)*8.5); top: calc(var(--u) * 3.1); bottom: calc(var(--u)*0.6);
42	  border-radius: calc(var(--u) * 5); background: linear-gradient(180deg, #8b34c4, #4d128a); border: calc(var(--u)*0.45) solid #ffcd5a;
43	  box-shadow: 0 0 calc(var(--u)*2) rgba(255,200,90,0.7), inset 0 calc(var(--u)*0.5) calc(var(--u)*0.6) rgba(255,255,255,0.3);
44	  display: flex; align-items: center; justify-content: center; text-align: center; }
