46	  background: linear-gradient(180deg, #fffaf0, #ffe08a 60%, #ffc548); -webkit-background-clip: text; background-clip: text; color: transparent;
47	  filter: drop-shadow(0 calc(var(--u)*0.18) 0 rgba(70,0,80,0.7)); }
48	#hud .victory .medal { position: absolute; left: 50%; top: 0; transform: translateX(-50%); width: calc(var(--u)*6.2); height: calc(var(--u)*6.2); }
49	#hud .victory .laurel { position: absolute; top: calc(var(--u)*3.6); width: calc(var(--u)*9.5); height: calc(var(--u)*9.8); }
