51	#hud .victory .laurel.r { right: calc(var(--u)*1.0); transform: scaleX(-1); }
52	#hud .victory.pop { animation: rbPop 0.7s cubic-bezier(.2,1.6,.4,1) both; }
53	@keyframes rbPop { from { transform: translateX(-50%) scale(0.2); opacity: 0; } to { transform: translateX(-50%) scale(1); opacity: 1; } }
54	#hud .replay { position: absolute; left: 50%; bottom: calc(var(--u) * 18.5); transform: translateX(-50%); pointer-events: auto; cursor: pointer;
55	  font-weight: 800; font-size: calc(var(--u)*2.2); color: #fff; padding: calc(var(--u)*0.6) calc(var(--u)*2.4); border-radius: calc(var(--u)*2);
56	  background: rgba(110,30,170,0.75); border: calc(var(--u)*0.2) solid #ffd36b; }
57	#hud .pausedOverlay { position: absolute; inset: 0; background: rgba(40,0,70,0.45); display: flex; align-items: center; justify-content: center; pointer-events: auto; }
58	#hud .pausedOverlay div { font-weight: 800; font-size: calc(var(--u)*4); color: #fff; text-shadow: 0 0 calc(var(--u)*1) #b04ad8; }
59	#hud .hint { position: absolute; bottom: calc(var(--u)*4); left: 50%; transform: translateX(-50%); color: rgba(255,255,255,0.85); font-weight: 700; font-size: calc(var(--u)*1.8);
60	  text-shadow: 0 0 calc(var(--u)*0.6) rgba(120,0,160,0.9); }
61	#hud .flash { position: absolute; inset: 0; background: rgba(255,80,140,0.0); transition: background 0.25s; }
