74	export interface Hud {
75	  setVisible(v: boolean): void;
76	  setStage(id: StageId): void;
77	  setCoins(n: number): void;
78	  setHearts(n: number, max?: number): void;
79	  showVictory(v: boolean, animate?: boolean): void;
80	  showPaused(v: boolean): void;
81	  showHint(text: string | null): void;
82	  flashHurt(): void;
83	  onPause(cb: () => void): void;
84	  onReplay(cb: () => void): void;
85	  root: HTMLElement;
86	}
87	
88	export function createHud(): Hud {
89	  const style = document.createElement('style');
90	  style.textContent = CSS;
91	  document.head.appendChild(style);
92	  const root = document.createElement('div');
93	  root.id = 'hud';
94	  root.innerHTML = `<div class="frame">
95	    <div class="flash"></div>
96	    <div class="bar">
97	      <div class="seg hearts">${HEART}<span class="num" data-k="hearts">5/5</span><span class="plus">+</span></div>
98	      <div class="seg coins">${COIN}<span class="num" data-k="coins">1,330</span></div>
99	      <div class="seg pause"><div class="pbtn" data-k="pause"><i></i><i></i></div></div>
100	    </div>
101	    <div class="banner"><span data-k="title">03 · WHIRLPOOL TWIRL</span></div>
102	    <div class="victory hidden"><div class="laurel l">${LAUREL}</div><div class="laurel r">${LAUREL}</div><div class="pill"><span>FINAL SPIN<br>COMPLETE</span></div><div class="medal">${MEDAL}</div></div>
103	    <div class="replay hidden" data-k="replay">↻ Replay</div>
104	    <div class="hint hidden"></div>
105	    <div class="pausedOverlay hidden"><div>PAUSED</div></div>
106	  </div>`;
107	  document.body.appendChild(root);
108	  const $ = (k: string) => root.querySelector(`[data-k="${k}"]`) as HTMLElement;
109	  const bar = root.querySelector('.bar') as HTMLElement;
110	  const banner = root.querySelector('.banner') as HTMLElement;
111	  const victory = root.querySelector('.victory') as HTMLElement;
112	  const paused = root.querySelector('.pausedOverlay') as HTMLElement;
113	  const hint = root.querySelector('.hint') as HTMLElement;
114	  const flash = root.querySelector('.flash') as HTMLElement;
115	  let pauseCb = () => {};
116	  let replayCb = () => {};
117	  $('pause').addEventListener('pointerdown', (e) => { e.stopPropagation(); pauseCb(); });
118	  paused.addEventListener('pointerdown', (e) => { e.stopPropagation(); pauseCb(); });
119	  $('replay').addEventListener('pointerdown', (e) => { e.stopPropagation(); replayCb(); });
120	  return {
121	    root,
122	    setVisible(v) { bar.classList.toggle('hidden', !v); banner.classList.toggle('hidden', !v); },
123	    setStage(id) { $('title').textContent = `${id} · ${STAGE_TITLES[id]}`; },
124	    setCoins(n) { $('coins').textContent = n.toLocaleString('en-US'); },
125	    setHearts(n, max = 5) { $('hearts').textContent = `${n}/${max}`; },
126	    showVictory(v, animate = true) {
127	      victory.classList.toggle('hidden', !v);
128	      victory.classList.toggle('pop', v && animate);
129	      $('replay').classList.add('hidden');
130	      if (v) setTimeout(() => { if (!victory.classList.contains('hidden')) $('replay').classList.remove('hidden'); }, 2600);
131	    },
132	    showPaused(v) { paused.classList.toggle('hidden', !v); },
133	    showHint(t) { hint.classList.toggle('hidden', !t); hint.textContent = t ?? ''; },
134	    flashHurt() { flash.style.background = 'rgba(255,80,140,0.35)'; setTimeout(() => (flash.style.background = 'rgba(255,80,140,0)'), 180); },
135	    onPause(cb) { pauseCb = cb; },
136	    onReplay(cb) { replayCb = cb; },
137	  };
138	}
