1	/**
2	 * Gold $ coins anchored to the course (s, lateral, height). Real pickups: distance test against
3	 * Benny each frame; collected coins pop + sparkle and the counter increments by COIN_VALUE.
4	 * Layout follows the coin trails visible in the references (03 spiral trail, 04 left edge,
5	 * 05/07 snaking centre line, 06 on the arch crest, 08–10 toward the towel).
6	 */
7	import * as THREE from 'three';
8	import type { Course, StageId } from '../world/course';
9	import { canvasTexture } from '../world/materials';
10	import { coreLateral } from '../vfx/waterRibbon';
11	
12	export const COIN_VALUE = 10;
13	
14	/** scale: coin size factor (1 = 1.0 u diameter); tilt: radians the coin leans back (top away from the camera) */
15	export interface CoinDef { s: number; lat: number; h: number; stage: StageId; scale?: number; tilt?: number }
16	
17	/**
18	 * 05 (ref 05, measured): ≈10 coins on the electric-cyan core winding to the VP. The nearest one is
19	 * ≈95 px wide just above Benny's pom (474, 726), then 64 → 55 → 42 → 28 → 19 px: the spacing in depth
20	 * grows with distance, so the gaps here grow too (C05.gap0 + k·C05.gapGrow). Coins lean back by C05.tilt
21	 * so their face reads as a slightly flattened disc with the rim visible underneath, as in the ref.
22	 * Before the 05 checkpoint the trail keeps a plain C05.gap0 spacing (gameplay only, never in frame).
23	 */
24	export const C05 = { first: 5.7, gap0: 5.0, gapGrow: 1.5, gapMax: 8, scale: 0.9, h: 1.2, tilt: 0.8, preGap: 3.6, latK: 0.7 };
25	
26	function coins05(course: Course, add: (stage: StageId, s: number, lat: number, h?: number, extra?: Partial<CoinDef>) => void) {
27	  const a = course.stage('05');
28	  const sCp = course.marks['05_crest'];
29	  const extra = { scale: C05.scale, tilt: C05.tilt };
30	  const ss: number[] = [];
31	  // gameplay trail before the checkpoint ends 1 u behind Benny's checkpoint spot (never between him and the camera view)
32	  for (let s = sCp - 1; s > a.s0 + 6; s -= C05.preGap) ss.unshift(s);
33	  for (let k = 0, s = sCp + C05.first; s < a.s1 - 3; k++) { ss.push(s); s += Math.min(C05.gapMax, C05.gap0 + k * C05.gapGrow); }
34	  // latK < 1: the trail winds with the cyan core but stays inside its middle (the core half width is
35	  // ≥ 2 u), so the far coins converge on the VP like the ref instead of swinging out to the pink bands
36	  for (const s of ss) add('05', s, C05.latK * coreLateral(course, s), C05.h, extra);
37	}
38	
39	export function coinLayout(course: Course): CoinDef[] {
40	  const out: CoinDef[] = [];
41	  const add = (stage: StageId, s: number, lat: number, h = 0.9, extra: Partial<CoinDef> = {}) => out.push({ s, lat, h, stage, ...extra });
42	  const st = (id: StageId) => course.stage(id);
43	  // 03 — spiral trail ahead of Benny toward the drain
44	  { const a = st('03'); for (let i = 0; i < 9; i++) add('03', a.s0 + 6 + i * 2.7, 0.9 - i * 0.12); }
45	  // 04 — along the left edge of the slide
46	  { const a = st('04'); for (let i = 0; i < 8; i++) add('04', a.s0 + 9 + i * 3.6, -1.35); }
47	  // 05 — on the winding cyan core (see C05)
48	  coins05(course, add);
49	  // 06 — up and over the crest (left of centre like the ref)
50	  { const a = st('06'); const n = 18; for (let i = 0; i < n; i++) { const s = a.s0 + 4 + i * ((a.s1 - a.s0 - 6) / n); add('06', s, -1.3 + 0.7 * Math.sin(i * 0.4)); } }
51	  // 07 — winding trail, continuing down the plunge
52	  { const a = st('07'); const n = 24; for (let i = 0; i < n; i++) { const s = a.s0 + 6 + i * ((a.s1 - a.s0 - 10) / n); add('07', s, 1.0 * Math.sin(i * 0.5 + 1)); } }
53	  // 08 — S toward the platform
54	  { const a = st('08'); for (let i = 0; i < 8; i++) add('08', a.s0 + 3 + i * 1.9, -0.6 + 0.9 * Math.sin(i * 0.8)); }
55	  // 09 — arc along the left (inside of the bend, under the wave)
56	  { const a = st('09'); for (let i = 0; i < 9; i++) add('09', a.s0 + 1.5 + i * 1.7, -1.7 + i * 0.12); }
57	  // 10 — straight line into the towel tunnel
58	  { const a = st('10'); for (let i = 0; i < 5; i++) add('10', a.s0 + 1.5 + i * 2.0, -0.15); }
59	  return out;
60	}
61	
62	export interface CoinSystem {
63	  group: THREE.Group;
64	  defs: CoinDef[];
65	  collected: Uint8Array;
66	  /** returns number of coins picked up this frame */
67	  update(time: number, dt: number, bennyS: number, bennyLat: number): number;
68	  /** mark coins before s as collected (deterministic QA checkpoint state) or reset all */
69	  resetUntil(s: number): void;
70	}
71	
72	export function createCoins(course: Course): CoinSystem {
73	  const defs = coinLayout(course);
74	  const faceTex = canvasTexture(256, 256, (c, w, h) => {
75	    const g = c.createRadialGradient(w * 0.38, h * 0.32, 10, w / 2, h / 2, w * 0.55);
76	    g.addColorStop(0, '#ffe680');
77	    g.addColorStop(0.45, '#ffcf2a');
78	    g.addColorStop(1, '#e89200');
79	    c.fillStyle = g;
80	    c.beginPath(); c.arc(w / 2, h / 2, w / 2, 0, Math.PI * 2); c.fill();
81	    // raised inner rim: dark groove + bright lip
82	    c.lineWidth = 9;
83	    c.strokeStyle = '#c98200'; c.beginPath(); c.arc(w / 2 + 2, h / 2 + 2, w * 0.4, 0, Math.PI * 2); c.stroke();
84	    c.strokeStyle = '#fff0a0'; c.beginPath(); c.arc(w / 2 - 1, h / 2 - 1, w * 0.4, 0, Math.PI * 2); c.stroke();
85	    // embossed "$" drawn as vector strokes (font-independent: identical on every Android device):
86	    // light bevel up-left, dark bevel down-right, deep-gold glyph on top
87	    const dollar = (dx: number, dy: number, col: string, lw: number) => {
88	      c.save(); c.translate(dx, dy);
89	      c.strokeStyle = col; c.lineCap = 'round'; c.lineJoin = 'round';
90	      c.lineWidth = lw;
91	      c.beginPath();
92	      c.moveTo(166, 90);
93	      c.bezierCurveTo(150, 66, 90, 64, 90, 98);
94	      c.bezierCurveTo(90, 128, 166, 124, 166, 160);
95	      c.bezierCurveTo(166, 196, 104, 198, 88, 168);
96	      c.stroke();
97	      c.lineWidth = lw * 0.62;
98	      c.beginPath(); c.moveTo(128, 50); c.lineTo(128, 206); c.stroke();
99	      c.restore();
100	    };
101	    dollar(3, 4, '#7a3c00', 32); // drop shadow
102	    dollar(0, 0, '#b86400', 30); // dark outline
103	    dollar(0, 0, '#ffe55a', 18); // bright raised glyph
104	    dollar(-3, -3, '#fff8d0', 6); // top-left bevel highlight
105	  });
106	  // the cylinder cap's UVs run sideways once the coin is stood up (rotateX): turn the face art upright
107	  faceTex.center.set(0.5, 0.5);
108	  faceTex.rotation = -Math.PI / 2;
109	  // milled (ridged) gold edge, as on the ref coins
110	  const edgeTex = canvasTexture(256, 8, (c, w, h) => {
111	    for (let x = 0; x < w; x += 4) { c.fillStyle = (x / 4) % 2 ? '#c08000' : '#ffe070'; c.fillRect(x, 0, 4, h); }
112	  });
113	  const geo = new THREE.CylinderGeometry(0.5, 0.5, 0.2, 48, 1);
114	  geo.rotateX(Math.PI / 2); // faces along ±Z
115	  // Gold is carried mostly by EMISSIVE art (blue ≈ 0) so the pink-white candy environment and the
116	  // Neutral tone mapping cannot wash it to pale peach (ref face ≈ #F4C400); a dark-gold metal base
117	  // keeps a reflective sheen on top.
118	  const side = new THREE.MeshStandardMaterial({ color: '#6a4a00', metalness: 0.75, roughness: 0.3, emissive: '#ffffff', emissiveMap: edgeTex, emissiveIntensity: 1.0 });
119	  const face = new THREE.MeshStandardMaterial({ map: faceTex, color: '#7a5200', metalness: 0.7, roughness: 0.3, emissive: '#ffffff', emissiveMap: faceTex, emissiveIntensity: 1.15 });
120	  const mesh = new THREE.InstancedMesh(geo, [side, face, face], defs.length);
121	  mesh.frustumCulled = false;
122	  const group = new THREE.Group();
123	  group.name = 'coins';
124	  group.add(mesh);
125	  const collected = new Uint8Array(defs.length);
126	  const popT = new Float32Array(defs.length).fill(-1);
127	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), basis = new THREE.Matrix4();
128	  const p = new THREE.Vector3(), sc = new THREE.Vector3();
129	  const spin = new THREE.Quaternion(), axis = new THREE.Vector3();
130	  const tiltQ = new THREE.Quaternion(), xAxis = new THREE.Vector3(1, 0, 0);
131	  const back = new THREE.Vector3();
132	
